/**
 * @suppress
 */
public object FfiConverterTypeEmbedHandle: FfiConverter<EmbedHandle, Long> {
    override fun lower(value: EmbedHandle): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): EmbedHandle {
        return EmbedHandle(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): EmbedHandle {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: EmbedHandle) = 8UL

    override fun write(value: EmbedHandle, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



