enum class CloseReason {
    
    REQUESTED,
    INTERNAL;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeCloseReason: FfiConverterRustBuffer<CloseReason> {
    override fun read(buf: ByteBuffer) = try {
        CloseReason.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: CloseReason) = 4UL

    override fun write(value: CloseReason, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





