    {
        

        companion object
    }
    
    data class SetTokenEndpoint(
        val `url`: kotlin.String, 
        val `headers`: List<com.getlingara.embed.Header>) : Command()
        
    {
        

        companion object
    }
    
    object StreamPause : Command()
    
    
    object StreamResume : Command()
    
    
    data class SendContext(
