/**
 * @suppress
 */
public object FfiConverterTypeCommand : FfiConverterRustBuffer<Command>{
    override fun read(buf: ByteBuffer): Command {
        return when(buf.getInt()) {
            1 -> Command.ProvideToken(
                FfiConverterTypeSecretString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> Command.ProvideTokenFor(
                FfiConverterTypeSecretString.read(buf),
                FfiConverterLong.read(buf),
                )
            3 -> Command.TokenUnavailable(
                FfiConverterString.read(buf),
                )
            4 -> Command.SetTokenEndpoint(
                FfiConverterString.read(buf),
                FfiConverterSequenceTypeHeader.read(buf),
                )
            5 -> Command.StreamPause
            6 -> Command.StreamResume
            7 -> Command.SendContext(
                FfiConverterTypeWorldContext.read(buf),
                )
            8 -> Command.PracticeStart(
                FfiConverterTypePracticeSource.read(buf),
                )
            9 -> Command.PracticeSnapshot(
                FfiConverterLong.read(buf),
                )
            10 -> Command.PracticeAnswer(
                FfiConverterLong.read(buf),
                FfiConverterString.read(buf),
                )
            11 -> Command.PracticeChoose(
                FfiConverterLong.read(buf),
                FfiConverterLong.read(buf),
                )
            12 -> Command.PracticeReveal(
                FfiConverterLong.read(buf),
                )
            13 -> Command.PracticeSelfGrade(
                FfiConverterLong.read(buf),
                FfiConverterBoolean.read(buf),
                )
            14 -> Command.PracticeNext(
                FfiConverterLong.read(buf),
                )
            15 -> Command.PracticeFinish(
                FfiConverterLong.read(buf),
                )
            16 -> Command.DialogueOpen(
                FfiConverterTypeDialogueConfig.read(buf),
                )
            17 -> Command.DialogueSay(
                FfiConverterLong.read(buf),
                FfiConverterString.read(buf),
                )
            18 -> Command.DialogueSetLevel(
                FfiConverterLong.read(buf),
                FfiConverterInt.read(buf),
                )
            19 -> Command.DialogueSetScene(
                FfiConverterLong.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            20 -> Command.DialogueCancel(
                FfiConverterLong.read(buf),
                )
            21 -> Command.DialogueClose(
                FfiConverterLong.read(buf),
                )
            22 -> Command.DialogueSnapshot(
                FfiConverterLong.read(buf),
                )
            23 -> Command.DialogueLoad(
                FfiConverterTypeDialogueSource.read(buf),
                FfiConverterTypeGraphSession.read(buf),
                )
            24 -> Command.DialogueSetFact(
                FfiConverterLong.read(buf),
                FfiConverterString.read(buf),
                FfiConverterTypeFactValue.read(buf),
                )
            25 -> Command.DialogueValidate(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Command) = when(value) {
        is Command.ProvideToken -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeSecretString.allocationSize(value.`token`)
                + FfiConverterString.allocationSize(value.`expiresAt`)
            )
        }
        is Command.ProvideTokenFor -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeSecretString.allocationSize(value.`token`)
                + FfiConverterLong.allocationSize(value.`expiresInSecs`)
            )
        }
        is Command.TokenUnavailable -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is Command.SetTokenEndpoint -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`url`)
