/**
 * @suppress
 */
public object FfiConverterTypeCommandOutcome : FfiConverterRustBuffer<CommandOutcome>{
    override fun read(buf: ByteBuffer): CommandOutcome {
        return when(buf.getInt()) {
            1 -> CommandOutcome.Done
            2 -> CommandOutcome.Id(
                FfiConverterLong.read(buf),
                )
            3 -> CommandOutcome.Practice(
                FfiConverterOptionalTypePracticeSnapshot.read(buf),
                )
            4 -> CommandOutcome.Dialogue(
                FfiConverterOptionalTypeDialogueSnapshot.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CommandOutcome) = when(value) {
        is CommandOutcome.Done -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CommandOutcome.Id -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterLong.allocationSize(value.`id`)
            )
        }
        is CommandOutcome.Practice -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalTypePracticeSnapshot.allocationSize(value.`snapshot`)
            )
        }
