            (
                4UL
                + FfiConverterOptionalTypeDialogueSnapshot.allocationSize(value.`snapshot`)
            )
        }
    }

    override fun write(value: CommandOutcome, buf: ByteBuffer) {
        when(value) {
            is CommandOutcome.Done -> {
                buf.putInt(1)
                Unit
            }
            is CommandOutcome.Id -> {
                buf.putInt(2)
