        is EmbedEvent.Error -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeEmbedError.allocationSize(value.`error`)
            )
        }
        is EmbedEvent.Log -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeLogLevel.allocationSize(value.`level`)
                + FfiConverterString.allocationSize(value.`target`)
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
        is EmbedEvent.Closed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeCloseReason.allocationSize(value.`reason`)
            )
        }
        is EmbedEvent.Unknown -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`typeTag`)
                + FfiConverterString.allocationSize(value.`json`)
            )
        }
    }

    override fun write(value: EmbedEvent, buf: ByteBuffer) {
        when(value) {
            is EmbedEvent.TokenNeeded -> {
                buf.putInt(1)
                FfiConverterLong.write(value.`request`, buf)
                FfiConverterTypeTokenReason.write(value.`reason`, buf)
                Unit
            }
            is EmbedEvent.Stream -> {
                buf.putInt(2)
                FfiConverterTypeStreamState.write(value.`state`, buf)
                FfiConverterOptionalString.write(value.`cursor`, buf)
                Unit
            }
            is EmbedEvent.Lingara -> {
                buf.putInt(3)
                FfiConverterTypeLingaraEvent.write(value.`event`, buf)
                Unit
            }
            is EmbedEvent.WorldSent -> {
                buf.putInt(4)
                FfiConverterLong.write(value.`request`, buf)
                FfiConverterString.write(value.`eventId`, buf)
                FfiConverterOptionalTypeReaction.write(value.`reaction`, buf)
                Unit
            }
            is EmbedEvent.Practice -> {
                buf.putInt(5)
                FfiConverterLong.write(value.`session`, buf)
                FfiConverterTypePracticeSnapshot.write(value.`snapshot`, buf)
                Unit
            }
            is EmbedEvent.NpcTurn -> {
                buf.putInt(6)
                FfiConverterLong.write(value.`dialogue`, buf)
                FfiConverterLong.write(value.`request`, buf)
                FfiConverterTypeNpcTurnUpdate.write(value.`update`, buf)
                Unit
            }
            is EmbedEvent.CheckpointReached -> {
                buf.putInt(7)
                FfiConverterLong.write(value.`dialogue`, buf)
                FfiConverterString.write(value.`checkpoint`, buf)
                FfiConverterOptionalString.write(value.`edge`, buf)
                FfiConverterTypeCrossedVia.write(value.`via`, buf)
                Unit
            }
            is EmbedEvent.DialogueEnded -> {
                buf.putInt(8)
                FfiConverterLong.write(value.`dialogue`, buf)
                FfiConverterTypeDialogueOutcome.write(value.`outcome`, buf)
                FfiConverterString.write(value.`checkpoint`, buf)
                FfiConverterOptionalString.write(value.`edge`, buf)
                Unit
            }
            is EmbedEvent.DialogueLoaded -> {
                buf.putInt(9)
                FfiConverterLong.write(value.`dialogue`, buf)
                FfiConverterString.write(value.`dialogueId`, buf)
                FfiConverterLong.write(value.`rev`, buf)
                Unit
            }
            is EmbedEvent.DialogueLoadFailed -> {
                buf.putInt(10)
                FfiConverterLong.write(value.`dialogue`, buf)
                FfiConverterTypeEmbedError.write(value.`error`, buf)
                Unit
            }
            is EmbedEvent.Error -> {
                buf.putInt(11)
                FfiConverterTypeEmbedError.write(value.`error`, buf)
                Unit
            }
            is EmbedEvent.Log -> {
                buf.putInt(12)
                FfiConverterTypeLogLevel.write(value.`level`, buf)
                FfiConverterString.write(value.`target`, buf)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is EmbedEvent.Closed -> {
                buf.putInt(13)
                FfiConverterTypeCloseReason.write(value.`reason`, buf)
                Unit
            }
            is EmbedEvent.Unknown -> {
                buf.putInt(14)
                FfiConverterString.write(value.`typeTag`, buf)
                FfiConverterString.write(value.`json`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
