 */
sealed class EmbedException: kotlin.Exception() {
    
    class Failed(
        
        val `error`: EmbedError
        ) : EmbedException() {
        override val message
            get() = "error=${ `error` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<EmbedException> {
        override fun lift(error_buf: RustBuffer.ByValue): EmbedException = FfiConverterTypeEmbedException.lift(error_buf)
    }

    
}

/**
