    }

    override fun write(value: StreamState, buf: ByteBuffer) {
        when(value) {
            is StreamState.Connecting -> {
                buf.putInt(1)
                Unit
            }
            is StreamState.Live -> {
                buf.putInt(2)
                Unit
            }
            is StreamState.Paused -> {
                buf.putInt(3)
                Unit
            }
            is StreamState.Down -> {
                buf.putInt(4)
                FfiConverterTypeEmbedError.write(value.`error`, buf)
                FfiConverterLong.write(value.`retryInMs`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






enum class TokenReason {
    
    INITIAL,
    EXPIRING,
    REJECTED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeTokenReason: FfiConverterRustBuffer<TokenReason> {
    override fun read(buf: ByteBuffer) = try {
        TokenReason.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: TokenReason) = 4UL

    override fun write(value: TokenReason, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * Where tokens come from. `Poll` raises `TokenNeeded`; `Http` POSTs `{}`
 * to the game's own URL from K1's thread.
 */
sealed class TokenSourceConfig {
    
    object Poll : TokenSourceConfig()
    
    
    data class Http(
        val `url`: kotlin.String, 
        val `headers`: List<com.getlingara.embed.Header>) : TokenSourceConfig()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeTokenSourceConfig : FfiConverterRustBuffer<TokenSourceConfig>{
    override fun read(buf: ByteBuffer): TokenSourceConfig {
        return when(buf.getInt()) {
            1 -> TokenSourceConfig.Poll
            2 -> TokenSourceConfig.Http(
                FfiConverterString.read(buf),
                FfiConverterSequenceTypeHeader.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TokenSourceConfig) = when(value) {
        is TokenSourceConfig.Poll -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is TokenSourceConfig.Http -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`url`)
                + FfiConverterSequenceTypeHeader.allocationSize(value.`headers`)
            )
        }
    }

    override fun write(value: TokenSourceConfig, buf: ByteBuffer) {
        when(value) {
            is TokenSourceConfig.Poll -> {
                buf.putInt(1)
                Unit
            }
            is TokenSourceConfig.Http -> {
                buf.putInt(2)
                FfiConverterString.write(value.`url`, buf)
                FfiConverterSequenceTypeHeader.write(value.`headers`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






