/**
 * @suppress
 */
public object FfiConverterMapStringTypeFactValue: FfiConverterRustBuffer<Map<kotlin.String, FactValue>> {
    override fun read(buf: ByteBuffer): Map<kotlin.String, FactValue> {
        val len = buf.getInt()
        return buildMap<kotlin.String, FactValue>(len) {
            repeat(len) {
                val k = FfiConverterString.read(buf)
                val v = FfiConverterTypeFactValue.read(buf)
                this[k] = v
            }
        }
    }

    override fun allocationSize(value: Map<kotlin.String, FactValue>): ULong {
        val spaceForMapSize = 4UL
        val spaceForChildren = value.map { (k, v) ->
            FfiConverterString.allocationSize(k) +
            FfiConverterTypeFactValue.allocationSize(v)
        }.sum()
        return spaceForMapSize + spaceForChildren
    }

    override fun write(value: Map<kotlin.String, FactValue>, buf: ByteBuffer) {
        buf.putInt(value.size)
        // The parens on `(k, v)` here ensure we're calling the right method,
        // which is important for compatibility with older android devices.
        // Ref https://blog.danlew.net/2017/03/16/kotlin-puzzler-whose-line-is-it-anyways/
        value.forEach { (k, v) ->
            FfiConverterString.write(k, buf)
            FfiConverterTypeFactValue.write(v, buf)
        }
    }
}





/**
 * Typealias from the type name used in the UDL file to the custom type.  This
 * is needed because the UDL type name is used in function/method signatures.
 * It's also what we have an external type that references a custom type.
 */
public typealias SecretString = Secret

/**
 * @suppress
 */
public object FfiConverterTypeSecretString: FfiConverter<SecretString, RustBuffer.ByValue> {
    override fun lift(value: RustBuffer.ByValue): SecretString {
        val builtinValue = FfiConverterString.lift(value)
        return Secret(builtinValue)
    }

    override fun lower(value: SecretString): RustBuffer.ByValue {
        val builtinValue = value.exposeSecret()
        return FfiConverterString.lower(builtinValue)
    }

    override fun read(buf: ByteBuffer): SecretString {
        val builtinValue = FfiConverterString.read(buf)
        return Secret(builtinValue)
    }

    override fun allocationSize(value: SecretString): ULong {
        val builtinValue = value.exposeSecret()
        return FfiConverterString.allocationSize(builtinValue)
    }

    override fun write(value: SecretString, buf: ByteBuffer) {
        val builtinValue = value.exposeSecret()
        FfiConverterString.write(builtinValue, buf)
    }
